window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-878b2abe1d69a8bb"]={"versions": [{"id": "FIG-878b2abe1d69a8bb", "releases": ["R1.5.1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Kontrollflusses der Funktion <code>E2E_P05Check()</code> innerhalb der AUTOSAR E2E-Bibliothek (AUTOSAR_PRS_E2EProtocol). Das Diagramm detailliert den Teilschritt „Read Counter“ für das E2E-Profil 5.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Kontext:</strong> Funktion <code>E2E_P05Check()</code> (gekennzeichnet durch den UML-Call-Behavior- bzw. Referenzrahmen oben links).\n</li><li><strong>Eingangsdaten:</strong> Byte-Array <code>Data[]</code> mit Byte-Offset-Zugriff <code>Data[Offset+2]</code>.\n</li><li><strong>Lokale Variable:</strong> <code>ReceivedCounter</code> vom Basistyp <code>uint8</code>.\n</li><li><strong>Aktion:</strong> Zuweisungs- bzw. Kopieraktion <code>Copy byte Data[Offset+2] in Little Endian order on uint8 local variable ReceivedCounter</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Start:</strong> Der Ablauf beginnt am Initialknoten (ausgefüllter schwarzer Kreis).\n</li><li><strong>Kopierschritt:</strong> Ausführung der Aktion zur Extraktion des Zählerwerts: Das Byte an der Position <code>Offset+2</code> des Puffers <code>Data</code> wird in Little-Endian-Byte-Reihenfolge in die lokale Variable <code>ReceivedCounter</code> übernommen.\n</li><li><strong>Ende:</strong> Der Kontrollfluss geht unmittelbar über eine gerichtete Kante in den Endknoten (Aktivitätsendknoten mit Doppelkreis) über.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Gemäß Anforderung <code>[PRS_E2E_00413]</code> ist die Implementierung des Prüfschritts „Read Counter“ innerhalb von <code>E2E_P05Check()</code> normativ bindend.\n</li><li>Das Counter-Feld in E2E-Profil 5 hat eine Breite von einem Byte (8 Bit) und liegt an Position <code>Offset + 2</code> im serialisierten Datenstrom. Da es sich um ein einzelnes Byte handelt, ist die Byte-Reihenfolge (Little Endian) trivial, legt jedoch formal die Orientierung im Datenlayout fest.\n</li><li>Der gelesene Wert <code>ReceivedCounter</code> dient nachfolgenden Prüfschritten (z. B. Delta-Counter-Prüfung) zur Fehler- und Wiederholungserkennung.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-0ab850f6162eb23c", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Kontrollflusses der Funktion <code>E2E_P05Check()</code> innerhalb der AUTOSAR E2E-Bibliothek (AUTOSAR_PRS_E2EProtocol). Das Diagramm detailliert den Teilschritt „Read Counter“ für das E2E-Profil 5.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Kontext:</strong> Funktion <code>E2E_P05Check()</code> (gekennzeichnet durch den UML-Call-Behavior- bzw. Referenzrahmen oben links).\n</li><li><strong>Eingangsdaten:</strong> Byte-Array <code>Data[]</code> mit Byte-Offset-Zugriff <code>Data[Offset+2]</code>.\n</li><li><strong>Lokale Variable:</strong> <code>ReceivedCounter</code> vom Basistyp <code>uint8</code>.\n</li><li><strong>Aktion:</strong> Zuweisungs- bzw. Kopieraktion <code>Copy byte Data[Offset+2] in Little Endian order on uint8 local variable ReceivedCounter</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Start:</strong> Der Ablauf beginnt am Initialknoten (ausgefüllter schwarzer Kreis).\n</li><li><strong>Kopierschritt:</strong> Ausführung der Aktion zur Extraktion des Zählerwerts: Das Byte an der Position <code>Offset+2</code> des Puffers <code>Data</code> wird in Little-Endian-Byte-Reihenfolge in die lokale Variable <code>ReceivedCounter</code> übernommen.\n</li><li><strong>Ende:</strong> Der Kontrollfluss geht unmittelbar über eine gerichtete Kante in den Endknoten (Aktivitätsendknoten mit Doppelkreis) über.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Gemäß Anforderung <code>[PRS_E2E_00413]</code> ist die Implementierung des Prüfschritts „Read Counter“ innerhalb von <code>E2E_P05Check()</code> normativ bindend.\n</li><li>Das Counter-Feld in E2E-Profil 5 hat eine Breite von einem Byte (8 Bit) und liegt an Position <code>Offset + 2</code> im serialisierten Datenstrom. Da es sich um ein einzelnes Byte handelt, ist die Byte-Reihenfolge (Little Endian) trivial, legt jedoch formal die Orientierung im Datenlayout fest.\n</li><li>Der gelesene Wert <code>ReceivedCounter</code> dient nachfolgenden Prüfschritten (z. B. Delta-Counter-Prüfung) zur Fehler- und Wiederholungserkennung.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-878b2abe1d69a8bb", "to": "FIG-0ab850f6162eb23c", "fr": "R19-03", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
